TLM.f("Tempora/Pasc4-5",{"officium":"Feria Sexta infra Hebdomadam IV post Octavam Paschæ","rule":["Oratio Dominica","Gloria","no Credo","Suffr=Maria3;Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Suffr=Maria3;Ecclesiæ,Papa;;"],"fallback":"Tempora/Pasc4-0","from":{"Introitus":"Tempora/Pasc4-0","Oratio":"Tempora/Pasc4-0","Lectio":"Tempora/Pasc4-0","Graduale":"Tempora/Pasc4-0","Evangelium":"Tempora/Pasc4-0","Offertorium":"Tempora/Pasc4-0","Secreta":"Tempora/Pasc4-0","Communio":"Tempora/Pasc4-0","Postcommunio":"Tempora/Pasc4-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 97:1; 97:2"},{"k":"text","la":"Cantáte Dómino cánticum novum, allelúja: quia mirabília fecit Dóminus, allelúja: ante conspéctum géntium revelávit justítiam suam, allelúja, allelúja, allelúja."},{"k":"ref","la":"Ps 97:1"},{"k":"text","la":"Salvávit sibi déxtera ejus: et bráchium sanctum ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Cantáte Dómino cánticum novum, allelúja: quia mirabília fecit Dóminus, allelúja: ante conspéctum géntium revelávit justítiam suam, allelúja, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Deus, qui fidélium mentes uníus éfficis voluntátis: da pópulis tuis id amáre quod prǽcipis, id desideráre quod promíttis; ut inter mundánas varietátes ibi nostra fixa sint corda, ubi vera sunt gáudia."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Jacóbi Apóstoli"},{"k":"ref","la":"Jas 1:17-21"},{"k":"text","la":"Caríssimi: Omne datum óptimum, et omne donum perféctum desúrsum est, descéndens a Patre lúminum, apud quem non est transmutátio nec vicissitúdinis obumbrátio. Voluntárie enim génuit nos verbo veritátis, ut simus inítium áliquod creatúræ ejus. Scitis, fratres mei dilectíssimi. Sit autem omnis homo velox ad audiéndum: tardus autem ad loquéndum et tardus ad iram. Ira enim viri justítiam Dei non operátur. Propter quod abjiciéntes omnem immundítiam et abundántiam malítiæ, in mansuetúdine suscípite ínsitum verbum, quod potest salváre ánimas vestras."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 117:16"},{"k":"text","la":"Déxtera Dómini fecit virtútem: déxtera Dómini exaltávit me. Allelúja."},{"k":"ref","la":"Rom 6:9"},{"k":"text","la":"Christus resúrgens ex mórtuis jam non móritur: mors illi ultra non dominábitur. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 16:5-14"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Vado ad eum, qui misit me: et nemo ex vobis intérrogat me: Quo vadis? Sed quia hæc locútus sum vobis, tristítia implévit cor vestrum. Sed ego veritátem dico vobis: expédit vobis, ut ego vadam: si enim non abíero, Paráclitus non véniet ad vos: si autem abíero, mittam eum ad vos. Et cum vénerit ille, árguet mundum de peccáto et de justítia et de judício. De peccáto quidem, quia non credidérunt in me: de justítia vero, quia ad Patrem vado, et jam non vidébitis me: de judício autem, quia princeps hujus mundi jam judicátus est. Adhuc multa hábeo vobis dícere: sed non potéstis portáre modo. Cum autem vénerit ille Spíritus veritátis, docébit vos omnem veritátem. Non enim loquétur a semetípso: sed quæcúmque áudiet, loquétur, et quæ ventúra sunt, annuntiábit vobis. Ille me clarificábit: quia de meo accípiet et annuntiábit vobis."}],"Offertorium":[{"k":"ref","la":"Ps 65:1-2; 65:16"},{"k":"text","la":"Jubiláte Deo, univérsa terra, psalmum dícite nómini ejus: veníte et audíte, et narrábo vobis, omnes qui timétis Deum, quanta fecit Dóminus ánimæ meæ, allelúja."}],"Secreta":[{"k":"text","la":"Deus, qui nos, per hujus sacrifícii veneránda commércia, uníus summæ divinitátis partícipes effecísti: præsta, quǽsumus; ut, sicut tuam cognóscimus veritátem, sic eam dignis móribus assequámur."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joann 16:8"},{"k":"text","la":"Cum vénerit Paráclitus Spíritus veritátis, ille árguet mundum de peccáto et de justítia et de judício, allelúja, allelúja."}],"Postcommunio":[{"k":"text","la":"Adésto nobis, Dómine, Deus noster: ut per hæc, quæ fidéliter súmpsimus, et purgémur a vítiis et a perículis ómnibus eruámur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"1a40e8a19758c5e5":{"t":"Ps 97, 1 i 2, Ps 97, 1\n(Ps 97, 1 i 2) Pjevajte Gospodinu novu pjesmu, <i>aleluja</i>,\njer Gospodin učini čudesa, <i>aleluja</i>.\nPred licem naroda otkri svoju pravdu, <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 97, 1) Pobjedu mu pribavi desnica njegova i sveta njegova ruka.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 97, 1 i 2) Pjevajte Gospodinu novu pjesmu, <i>aleluja</i>,\njer Gospodin učini čudesa, <i>aleluja</i>.\nPred licem naroda otkri svoju pravdu, <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Ps. 97, 1, 2). Pjevajte Gospodinu pjesmu novu, aleluja; jer je učinio divne stvari, aleluja; pred licem je naroda objavio pravdu svoju, aleluja, aleluja, aleluja. (Ps. 97, 1). Spasila nas desnica njegova, spasila nas ruka sveta njegova! Slava Ocu . . . Pjevajte . . , <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 324–325 (snimka 163) (OCR)"},"a1d003c5cd4f9d82":{"t":"<i>Pomolimo se</i>.\nBože, koji činiš da duše vjernika budu jedne volje, daj svojim vjernima da ljube što zapovijedaš i žele što obećavaš, te u nestalnosti svijeta naša srca budu postojano ondje gdje su prave radosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji činiš, da duše vjernih Tvojih budu jedne volje, daj narodima svojim, da ljube što Ti zapovijedaš, da žele, što Ti obećavaš, te u pro- V. nedjelja po Upkr.su mjenama svjetskim srca naSa prionu, gdje su prave radosti, po G. n.","knRef":"Kniewald 1942, str. 324–325 (snimka 163) (OCR)"},"35f2399b2fc87e38":{"t":"Jak 1, 17-21\nČitanje Poslanice bl. Jakova apostola. Predragi: svaki dobar dar i svaki savršen poklon odozgor je, naime, silazi od Oca svjetlosti, u kojega nema mijene ni sjene promjene. On nas je dobrovoljno rodio riječju istine da budemo prvenci njegovih stvorova. Znajte, moja predraga braćo, svatko mora biti brz na slušanje, a spor na govor i spor na srdžbu, jer u srdžbi čovjek ne čini što je pravedno pred Bogom. Zato odbacite svaku nečistoću i ostatak zlobe te ponizno prihvatite posijanu riječ koja može spasiti vaše duše.","v":"∅ → et","kn":"Čitanje poslanice bi. Jakova apostola (1, 17-21). Predragi! Svaki dobaT dar i svaki savršen poklon odozgo je dolazeći od Oca svijetla, u koga nema promjene ni sjenke od mijene. On nas je dragovoljno rodio po riječi istine, da budemo kao prvenci njegovih stvorova. Znajte, moja predraga braćo; neka bude svaki čovjek hitar da sluša, spor da govori, i spor na srdžbu. Jer u srdžbi ne čini . čovjek, što je pravedno pred Bogom. Zato odbacite svaku nečistoću i višak zlobe, u krotkosti prihvatite usađenu riječ, koja može spasiti vaše duše.","knRef":"Kniewald 1942, str. 326–327 (snimka 164) (OCR)"},"4ad6bf25e71c61bf":{"t":"Ps 117, 16, Rim 6, 9\n<i>Aleluja</i>, <i>aleluja</i>.\nDesnica je Gospodnja izvela junačko djelo, desnica me Gospodnja podigla, <i>aleluja</i>.\nKrist uskrsnuvši od mrtvih više ne umire. Smrt neće više vladati nad njim, <i>aleluja</i>.","kn":"Aleluja, aleluja (Ps. 117, 16). Desnica Gospodnja pokaza moć, desnica me Gospodnja uzvisi, aleluja. (Rim. 6, 9). Krist uskrsnuvši od mrtvih više ne umire, smrt više ne vlada nad njime, aleluja!","knRef":"Kniewald 1942, str. 326–327 (snimka 164) (OCR)"},"d8167a718105eb83":{"t":"Iv 16, 5-14\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme: Reče Isus svojim učenicima: Idem onome koji me je poslao, a nitko me od vas ne pita: Kamo ideš. Budući da sam vam ovo rekao, vaše se srce napunilo žalosti. Ali vam kažem istinu: Za vas je bolje da odem, jer ako ne odem neće k vama doći Tješitelj; a ako otiđem, poslat ću ga k vama. – Kad on dođe, prekorit će svijet zbog grijeha, zbog pravde i zbog osude. Zbog grijeha, jer nisu vjerovali u mene; zbog pravde, jer idem Ocu i više me nećete vidjeti; zbog osude, jer je poglavica ovoga svijeta već osuđen. Imao bih vam govoriti još mnogo toga, ali sada ne možete podnijeti. No kad dođe on, Duh istine, poučit će vas svu istinu, jer neće govoriti od sebe, nego će vam govoriti ono što čuje i objavit će vam buduće stvari. On će mene proslaviti, jer će uzeti od mojega i to vama objaviti.","kn":"t Slijedi sv. evanđelje po Ivanu (16, 5-14). U ono vrijeme reče Isus svojim učenicima: Idem k onomu, koji me posla, i nitko me od vas ne pita: Kamo ideš? A jer sam vam ovo rekao, žalošću se napuni vaše srce. Ali ja vam kažem istinu: Bolje vam je, da ja idem; jer ako ne otiđem, ne će k vama doći Utješitelj; a ako otiđem, pos^at ću ga k vama. A kada On dođe, prekorit će svijet radi grijeha, pravde i sudia. Radi grijeha, jer nijesu vjerovali u mene; radi pravde, jer idem k Ocu i ne ćete me više vidjeti; radi suda, jer je već osuđen poglavica ovoga svijeta. Imam vam kazati još mnogo, ali sada ne možete nositi. A kada dođe on, Duh ietine, poučit će vas svu istinu, jer ne će govoriti od sebe, nego će vam govoriti, što čuje, i objavit će vam buduće stvari. On će mene proslaviti, jer će uzeti od mojegai, i objavit će vam.","knRef":"Kniewald 1942, str. 326–327 (snimka 164) (OCR)"},"9c5bfd653e4c1dae":{"t":"Ps 65, 1-2 i 16\nKličite Bogu svi narodi, pjevajte psalme njegovu imenu. Dođite i slušajte svi koji se Boga bojite, pa ću vam pričati što je sve učinio mojoj duši, aleluja.","kn":"(Ps. 65, 1, 12, 16). Pokiikni Bogu sva zemljo, pjevajte pjesmu imenu njegovu; dođite i slušajte svi, koji se Bogai bojite, i kazivat ću vam, koliko Gospodin učini duši mojoj. Aleluja.","knRef":"Kniewald 1942, str. 326–327 (snimka 164) (OCR)"},"e35b3d1a2a657512":{"t":"Bože, koji si nas po časnoj zamjeni u ovoj žrtvi učinio dionicima naravi jedinoga Svevišnjeg božanstva, podaj, molimo, da kao što tvoju istinu upoznajemo tako je dostojnim životom slijedimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si nas časnim sudjelovanjem kod ove žrtve učinio zajedničarima jedinog previšnjeg Božanstva, podaj, .molimo, kao što znamo Tvoju istinu, da je tako i dostojnim vladanjem dostignemo, pp G. n.","knRef":"Kniewald 1942, str. 326–327 (snimka 164) (OCR)"},"1a0a565aa39e4fe3":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>u ovo</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"j Uistinu je dostojno i pravedno, pravo i spaso- I doba, ali osobito svečano na - današnji dan, (u ovo vrijeme), kad je žrtvovano naše vazmeno Janje, I Isukrst; jer On je pravo janje, koje je uzelo grijehe : svojim je uskrsnućem obnovio naš ž^vot. Zato pje- I vamo pjesmu Tvoje slave s anđelima i s arkanđe lima, s. prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"fc1d976598904cfe":{"t":"Iv 16, 8\nKad dođe Tješitelj, Duh istine, on će prekoriti svijet zbog grijeha, zbog pravde i zbog osude, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Iv. 16, 8). Kad dođe Tješitelj, Duh istine, on će pokarati svijet za grijeh i za pravdu i za sud, aleluja, aleluja.","knRef":"Kniewald 1942, str. 326–327 (snimka 164) (OCR)"},"841b94f7fe495931":{"t":"<i>Pomolimo se</i>.\nPomozi nam, Gospodine Bože, da se po ovom što u vjeri primismo od opačina očistimo i od svih pogibli izbavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","v":"postcomunio → ∅","kn":"Bliz nam budi, Gospodine, Bože naš, da se ovim svetinjama, koje vjerno primismo, i očistimo od opačina i od svih pogibli izbavimo, po G. n.","knRef":"Kniewald 1942, str. 326–327 (snimka 164) (OCR)"}}});
